import { TransKeyModel } from '~/entities/pin/api/dtos/types';

export const getLatestTranskeyModel = (fallback?: TransKeyModel | null): TransKeyModel | null => {
  try {
    const input = document.getElementById('userPin') as HTMLInputElement | null;
    const inputObj = window.mtk?.now?.inputObj ?? input;

    if (!input?.id || !inputObj || typeof window.mtk?.inputFillEncData !== 'function') {
      return fallback ?? null;
    }

    const values = window.mtk.inputFillEncData(inputObj);
    const hidden = values?.hidden;
    const hmac = values?.hmac;

    if (!hidden || !hmac) {
      return fallback ?? null;
    }

    const transkeyState = window.transkey?.[input.id];
    const seedKey = (document.getElementById('seedKey') as HTMLInputElement | null)?.value ?? '';

    return {
      id: input.id,
      hidden,
      hmac: String(hmac),
      keyboardType: transkeyState?.keyboardType,
      keyIndex: transkeyState?.keyIndex,
      fieldType: transkeyState?.fieldType,
      seedKey,
      initTime: window.initTime,
    };
  } catch {
    return fallback ?? null;
  }
};
